from review import card,save,DATE,DIRECTORY,write
import json
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)
def disposition(i,reason):
 qpath=DIRECTORY/'queue.json';q=json.loads(qpath.read_text());_,c=card(i)
 q['dispositions']=[v for v in q.get('dispositions',[]) if v['id']!=i]+[dict(id=i,title=c['title'],state='resolved',reason=reason,card='data/cards/'+i+'.json')];write(qpath,q)

i='TCS-2371';_,c=card(i);refs=c['references'];refs[0]['locator']='CCC 2023, article 8: Sections 1.1 and 1.2.1–1.2.2, Theorem 2; full version ECCC TR22-154, Section 7 read. The extra condition is bounded edge-edit cost between successive sizes, not an additional static expansion inequality.'
refs.append(dict(id='super2026',title='Quantitative Results on Super-Ramanujan Graphs',authors='Gil Cohen, Gal Maor',year=2026,url='https://eccc.weizmann.ac.il/report/2026/163/',locator='1 September 2026 preprint: introduction and Theorems 1.1–1.2 read. Quantitative one-sided existence and explicit bipartite constructions do not assert bounded edits between successive sizes.'))
save(i,dict(title='Growing Ramanujan graphs with bounded edge updates',formal='Do there exist a fixed integer d≥3, a constant c and an infinite unbounded set I of graph sizes, together with d-regular graphs Gₙ on the consistently labeled vertices {1,…,n} for n∈I, such that every Gₙ has max{λ₂(Gₙ),|λₙ(Gₙ)|}≤2√(d−1), and consecutive graphs in the family differ by at most c edge insertions and deletions?',definitions='Graphs are finite undirected loopless multigraphs, allowing parallel edges as in the source’s expanding-expander setting; each edge copy contributes one to each endpoint’s degree. A graph is d-regular when every vertex has degree d. Its symmetric adjacency matrix counts edge multiplicities and has real eigenvalues λ₁=d≥λ₂≥⋯≥λₙ. Here the Ramanujan condition bounds all eigenvalues except the top one, including the bottom eigenvalue in absolute value. In particular these graphs are connected and nonbipartite. For n∈I, let n⁺ be the least element of I larger than n. Compare Gₙ and Gₙ⁺ on their shared labels, adjoining the new labels as isolated vertices before inserting or deleting edges. The edit cost is Σ_{1≤u<v≤n⁺}|aₙ(u,v)−aₙ⁺(u,v)|, with aₙ(u,v)=0 if an endpoint exceeds n. The constant c is independent of n and may depend on the chosen fixed degree. New vertices remain in later graphs. Bounded cost also forces bounded gaps between consecutive sizes. The question asks for existence; no efficient construction, prescribed degree, exact cost such as 3d, or every-integer size set is imposed. The separate bipartite variant in the source excludes both trivial eigenvalues ±d and is not the condition displayed here.',question_type='yes_no',answer_criterion='Establish the existence of one such infinite family with fixed d≥3 and uniformly bounded edit cost, or rule out every such family. A construction may be nonexplicit. An additive ε>0 above the Ramanujan bound, or isolated Ramanujan graphs at each size with no bound on edits, does not meet the exact target.',context_blocks=[b('Expansion must survive growth','The same labeled network grows by adding vertices, while only constantly many edge copies may change at each step. Good graphs chosen independently at different sizes need not satisfy this condition.'),b('The spectral target is exact','For fixed degree, 2√(d−1) is the asymptotic benchmark for nontrivial adjacency eigenvalues. The source’s question asks to meet that threshold throughout the growing family.', 'primary'),b('An arbitrarily small fixed slack is already possible','For every even d≥6 and ε>0, the source proves existence of an infinite d-regular family with edit cost at most 3d and spectral bound 2√(d−1)+ε. Its proof does not give the ε=0 case.', 'primary'),b('Recent static constructions do not supply the edit guarantee','The September 2026 preprint gives improved spectral bounds for individual graph sizes, including explicit bipartite super-Ramanujan graphs. It does not assert that the graphs can be chosen to grow with bounded edge changes.', 'super2026')],why='Would show that optimal spectral connectivity is compatible with growing a bounded-degree network while rewiring only a bounded number of edges.',references=refs,progress=[dict(date='2023',text='Existence is proved with any fixed positive additive slack above the Ramanujan threshold, while the exact growing-family question is left open.',citation='primary'),dict(date='2026-09-01',text='A preprint strengthens static super-Ramanujan existence and construction guarantees; its theorems do not include growing-family edit bounds.',citation='super2026')],status='source_open',status_note='The full definition of expansion cost, the near-Ramanujan theorem and September 2026 results were checked. No resolution of the exact bounded-edit family was located through 12 September 2026.',model_self_contained=True,requires_context=False,importance=imp(c,'An existence question joining optimal spectral expansion with bounded rewiring under network growth.'),review_note='Replaced the misleading static reading of expanding with a consistently labeled sequence and an edge-copy edit bound. Selected the source’s basic existential nonbipartite question, allowing multigraphs, and separated explicitness and bipartite variants.',working_summary=sm(['The graph family must grow while changing only a bounded number of edges at each step.','Every graph must remain regular with one fixed degree and satisfy the exact Ramanujan spectral bound.','The labels of existing vertices persist, so independently choosing a good graph at each size is insufficient.','The source already constructs such growing families if any fixed positive spectral slack is allowed.','The open existence question asks whether that slack can be removed.'],['primary','super2026'])),notes=['Recovered bounded edits on consistently labeled growing multigraphs.','Defined the exact two-sided nontrivial spectral bound and distinguished the bipartite variant.','Retained bare existence without adding explicit construction or a prescribed optimal edit constant.','Checked September 2026 static results.'],checked_sources=[r['url'] for r in refs]+['https://eccc.weizmann.ac.il/report/2022/154/'])

i='TCS-2401';_,c=card(i);refs=c['references'];refs[0]['locator']='ICALP 2023, article 125: graph-transduction definition, Definition 2, Theorem 3 and final paragraph on page 125:5 read. The request is for a combinatorial characterization analogous to flip-flatness, not for flip-flatness itself to characterize NIP.'
refs.extend([dict(id='flip2024',title='Flip-Breakability: A Combinatorial Dichotomy for Monadically Dependent Graph Classes',authors='Jan Dreier, Nikolas Mählmann, Szymon Toruńczyk',year=2024,url='https://doi.org/10.1145/3618260.3649739',pdf_url='https://arxiv.org/pdf/2403.15201',locator='STOC 2024; full arXiv v2, 27 March 2024, introduction/transductions, Definition 1.2 and Theorem 1.3 read. All graph classes are covered, not only hereditary ones.'),dict(id='flip2025',title='Separability Properties of Monadically Dependent Graph Classes',authors='Édouard Bonnet, Samuel Braunfeld, Ioannis Eleftheriadis, Colin Geniet, Nikolas Mählmann, Michał Pilipczuk, Wojciech Przybyszewski, Szymon Toruńczyk',year=2025,url='https://doi.org/10.4230/LIPIcs.ICALP.2025.147',locator='ICALP 2025: Definition 2, Theorem 3 and discussion of the 2024 characterization read. Further characterization by weighted flip-separability.')])
save(i,dict(title='A combinatorial characterization of monadically NIP graph classes',formal='Resolved affirmatively: a class of finite graphs is monadically NIP if and only if it is flip-breakable. This supplies the purely combinatorial characterization requested in the 2023 source as an analogue of the flip-flatness characterization of monadic stability.',definitions='A graph is finite, undirected and simple. A graph class C transduces all graphs if there is one first-order formula φ(x,y), using adjacency, equality and a fixed finite list of unary vertex predicates, with this property: every finite graph H can be obtained by choosing G∈C, assigning arbitrary subsets of V(G) to those predicates, joining distinct vertices u,v whenever φ(u,v) or φ(v,u) holds in that colored G, and taking an induced subgraph isomorphic to H. First-order quantifiers range over vertices; φ and its predicate list must be fixed independently of H, while G and its coloring may vary. C is monadically NIP, also called monadically dependent, if no such φ exists. A k-flip of G partitions V(G) into at most k parts and independently complements or retains adjacency between each unordered pair of parts, permitting a pair to consist of the same part; loops are never added. The resulting graph has the same vertices. C is flip-breakable if, for every integer radius r≥0, there exist an integer kᵣ and a function Nᵣ:ℕ₊→ℕ₊ such that for every m≥1, every G∈C and every W⊆V(G) with |W|≥Nᵣ(m), there exist A,B⊆W with |A|,|B|≥m and a kᵣ-flip H of G for which dist_H(A,B)>r. Here dist_H(A,B) is the minimum shortest-path distance between one vertex of A and one of B, with distance infinity across components. The constants depend on C and r, not on G,W or m. No hereditary-closure assumption is required for this equivalence.',question_type='yes_no',answer_criterion='The affirmative answer is the published flip-breakability equivalence of Dreier, Mählmann and Toruńczyk, Theorem 1.3 in the full version. Its two directions exactly characterize all monadically NIP graph classes by a condition involving only graph partitions, adjacency changes, subsets and distances.',context_blocks=[b('The source asked to replace a logical condition by graph structure','Monadic NIP is defined through what a fixed logical formula can encode after arbitrary vertex coloring. The original request sought a purely combinatorial way to recognize the same class-level property.', 'primary'),b('Flip-flatness characterized the smaller stable setting','In the 2023 theorem, a bounded number of flips can make one large selected set pairwise far apart. The requested NIP analogue was not a claim that this same stronger condition would suffice.', 'primary'),b('The 2024 answer separates two large subsets','Flip-breakability requires two large sets to be far from each other after a bounded-part flip. Vertices within either set need not be far apart. This modified separation condition characterizes monadic dependence exactly.', 'flip2024'),b('Further structural progress followed','The 2025 paper supplies another equivalent condition, weighted flip-separability. This strengthens the available structural descriptions without changing the fact that the historical characterization question was already answered in 2024.', 'flip2025')],why='Provides a graph-theoretic structural foundation for a logical class believed to organize the boundary of efficient first-order model checking.',references=refs,progress=[dict(date='2023',text='Flip-flatness is proved equivalent to monadic stability; a comparable combinatorial characterization of monadic NIP is requested.',citation='primary'),dict(date='2024',text='STOC 2024 answers the question with the equivalence between monadic dependence and flip-breakability.',citation='flip2024'),dict(date='2025',text='ICALP 2025 adds the weighted flip-separability characterization.',citation='flip2025')],status='resolved',status_note='Resolved by the published STOC 2024 characterization. The source question, theorem, graph-class scope and quantifiers were matched and the subsequent ICALP 2025 treatment checked. This is literature and model verification, not independent verification of the proof or a proof-assistant certificate.',model_self_contained=True,requires_context=False,importance=imp(c,'A structural characterization linking finite model theory and dense graph structure.'),review_note='Recovered the comparison theorem, defined graph transductions and flip-breakability, and retired the obsolete open status without claiming that the broader model-checking conjecture follows.',working_summary=sm(['The source sought a purely combinatorial description of monadically NIP graph classes.','A 2024 theorem provides exactly such a description, called flip-breakability.','After bounded-part adjacency flips, any sufficiently large vertex set contains two large subsets far from each other.','This condition is equivalent to monadic NIP for arbitrary finite graph classes.','The historical question is resolved; the 2025 literature supplies an additional weighted separation characterization.'],['primary','flip2024','flip2025'])),notes=['Recovered the source’s analogy with flip-flatness rather than inventing an identical criterion.','Matched the published flip-breakability equivalence and defined both sides self-containedly.','Changed historical open status to resolved and distinguished the model-checking conjecture.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2403.15201'])
disposition(i,'Resolved by Dreier, Mählmann and Toruńczyk, STOC 2024: Theorem 1.3 characterizes all monadically dependent graph classes by flip-breakability, exactly answering the historical request for a combinatorial analogue of flip-flatness. Source/theorem match checked, including later ICALP 2025 treatment; no independent proof audit.')

i='TCS-2464';_,c=card(i);refs=c['references'];refs[0]['locator']='RANDOM 2023, article 36: Section 1 and Conjecture 1 read. Recovered the omitted conclusion, all six distributions and the d-local sampling model.'
refs.append(dict(id='uniform_resolution',title='Locally Sampleable Uniform Symmetric Distributions',authors='Daniel M. Kane, Anthony Ostuni, Kewen Wu',year=2025,url='https://arxiv.org/abs/2411.08183',locator='Published at STOC 2025; arXiv v2, 26 February 2025: Conjecture 1.1, Theorem 1.2, Theorem 4.1 and Remark 4.2 read. The approximation constant is independent of locality, and the theorem permits n₀ depending only on locality. Publication checked against the official STOC 2025 program.'))
save(i,dict(title='Six possibilities for locally sampled uniform symmetric distributions',formal='Resolved affirmatively: there exists an absolute constant C such that, for every fixed locality d and ε∈(0,1), all sufficiently large n have the following property. If a d-local Boolean map on independent uniform input bits has output distribution X at total variation distance at most ε from a distribution uniform on a nonempty union of Hamming-weight layers in {0,1}ⁿ, then X is within Cε of one of the six distributions defined below.',definitions='For m,n≥1, a map f:{0,1}ᵐ→{0,1}ⁿ is d-local if each output coordinate depends on at most d input coordinates; the chosen inputs may differ between outputs and may be shared. The input Uₘ is uniform on {0,1}ᵐ, and X is the law of f(Uₘ). There is no bound on m and no algorithmic uniformity requirement across n. For nonempty S⊆{0,…,n}, let U_Sⁿ be uniform on all strings x∈{0,1}ⁿ with |x|=Σⱼxⱼ∈S: every such string, rather than every allowed weight, has the same probability. For distributions P,Q on {0,1}ⁿ, TV(P,Q)=½Σₓ|P(x)−Q(x)|. The six comparison distributions are: a point mass at 0ⁿ; a point mass at 1ⁿ; equal mass on 0ⁿ and 1ⁿ; uniform on all even-weight strings; uniform on all odd-weight strings; and uniform on the entire cube. The quantifiers in the historical claim are ∃C>0 ∀d≥0 ∀ε∈(0,1) ∃n₀(d,ε) ∀n≥n₀ ∀m≥1 ∀d-local f ∀nonempty S: TV(f(Uₘ),U_Sⁿ)≤ε implies min_D TV(f(Uₘ),D)≤Cε, where D ranges over those six distributions. The result actually allows the threshold n₀ to depend only on d. No symmetry of f or of its output distribution is assumed.',question_type='yes_no',answer_criterion='The affirmative resolution is Theorem 4.1 of Kane, Ostuni and Wu, which proves the stated robust six-distribution classification, with an absolute multiplicative constant. Theorem 1.2 explicitly identifies this as the resolution of the Filmus–Leigh–Riazanov–Sokolov conjecture.',context_blocks=[b('The target is uniform over strings, not over weights','A symmetric support is a union of Hamming-weight layers. Larger layers contribute more mass because every supported string receives the same probability.'),b('Local output bits can still be correlated','Several output coordinates may use the same random input bit. Thus the sampler is not restricted to product distributions, and a low-locality map can even generate a uniform parity class.'),b('The conjecture is a robustness statement','The output need only be close to a uniform symmetric target. The conclusion says that this output must then be close to one of six simple distributions, with only a constant-factor loss in distance.', 'primary'),b('The full conjecture is now a theorem','Kane, Ostuni and Wu prove the classification in the work published at STOC 2025. All six comparison distributions themselves have exact samplers of locality at most two.', 'uniform_resolution')],why='Classifies the ability of constant-locality classical circuits to generate uniform symmetric distributions, including approximate generation rather than only exact sampling.',references=refs,progress=[dict(date='2023',text='The source conjectures the six-distribution classification and proves partial cases for supports concentrated on sublinear Hamming weights.',citation='primary'),dict(date='2025',text='The STOC paper proves the complete classification, with an approximation constant independent of locality.',citation='uniform_resolution')],status='resolved',status_note='Resolved by Kane, Ostuni and Wu, published at STOC 2025. The complete theorem, locality and distance conventions, absolute constant, threshold dependence and six distributions were checked against arXiv v2. This is published-theorem/model verification, not independent proof verification.',model_self_contained=True,requires_context=False,importance=imp(c,'A complete robust classification of locally sampleable uniform symmetric distributions.'),review_note='Replaced the truncated hypothesis with the complete implication and its published resolution. Defined total variation and uniform symmetric support, restored the full cube including weight zero, and avoided confusing locality with independent outputs.',working_summary=sm(['Each output bit of a local sampler reads only a bounded number of independent random input bits.','Suppose its output is close to a distribution uniform over a symmetric set of bit strings.','The output must then be close to one of six possibilities: two point masses, their equal mixture, two parity classes, or the whole cube.','The closeness loses only an absolute constant factor, independent of locality.','The 2023 conjecture was resolved in work published at STOC 2025.'],['primary','uniform_resolution'])),notes=['Recovered the full implication, locality model and all six comparison distributions.','Specified total variation, nonempty symmetric support and the universal constant.','Matched Theorem 4.1 and retired the obsolete open status.'],checked_sources=[r['url'] for r in refs]+['https://eccc.weizmann.ac.il/report/2024/180/','https://acm-stoc.org/stoc2025/accepted-papers.html'])
disposition(i,'Resolved by Kane, Ostuni and Wu, STOC 2025. Theorem 4.1 proves the original robust six-distribution classification with absolute approximation constant. Locality, uniform symmetric support, quantifiers and exact theorem statement checked; no independent proof audit.')
